#pragma once
#include "common.hpp"
#include <wincrypt.h>
namespace snuw {
inline std::string modelFileHash(const fs::path& path,const std::atomic_bool& cancel,uint64_t size,const std::function<void(uint64_t)>& progress){HCRYPTPROV provider=0;HCRYPTHASH hash=0;std::string result;try{if(!CryptAcquireContextW(&provider,nullptr,nullptr,PROV_RSA_AES,CRYPT_VERIFYCONTEXT)||!CryptCreateHash(provider,CALG_SHA_256,0,0,&hash))throw std::runtime_error("모델 해시를 준비하지 못했습니다.");std::ifstream input(fs::path(extendedWindowsPath(path)),std::ios::binary);if(!input)throw std::runtime_error("모델 파일을 열지 못했습니다.");std::vector<char> buffer(1024*1024);uint64_t count=0;ULONGLONG last=0;while(input){if(cancel)throw std::runtime_error("모델 파일 보내기를 중지했습니다.");input.read(buffer.data(),buffer.size());auto n=input.gcount();if(n>0){count+=uint64_t(n);if(count>size||!CryptHashData(hash,reinterpret_cast<BYTE*>(buffer.data()),DWORD(n),0))throw std::runtime_error("모델 파일이 바뀌었거나 해시를 계산하지 못했습니다.");if(GetTickCount64()-last>=200||count==size){progress(count);last=GetTickCount64();}}}if(!input.eof()||count!=size)throw std::runtime_error("모델 파일 크기가 바뀌었습니다.");BYTE bytes[32];DWORD length=32;if(!CryptGetHashParam(hash,HP_HASHVAL,bytes,&length,0))throw std::runtime_error("모델 해시를 읽지 못했습니다.");const char* hex="0123456789abcdef";for(auto byte:bytes){result+=hex[byte>>4];result+=hex[byte&15];}}catch(...){if(hash)CryptDestroyHash(hash);if(provider)CryptReleaseContext(provider,0);throw;}CryptDestroyHash(hash);CryptReleaseContext(provider,0);return result;}
}
